export const HARNESS_ICONS: Record<HarnessId, string> = {
  antigravity,
  claude,
  codex,
  cursor,
  grok,
  opencode,
  pi,
  omp,
  fx,
};

/** White marks that must follow `currentColor` so they stay visible in light mode. */
export const MONOCHROME_HARNESSES = new Set<HarnessId>([
  "cursor",
  "grok",
  "opencode",
  "pi",
  "fx",
]);

function MonoIcon({
  className,
  children,
  viewBox = "-4 -4 37 37",
}: {
  className: string;
  children: ReactNode;
  viewBox?: string;
}) {
  return (
    <svg
      viewBox={viewBox}
      fill="currentColor"
      aria-hidden
      className={`block ${className}`}
    >
      {children}
    </svg>
  );
}

